-- Proposed links from the two new Interdisciplinary strands, "The Nature of Schooling" and "The Languages of Being Human", to India records.
-- 43 links. Their relation type starts with proposed_, which the views show as "AI-drafted, unconfirmed". AI-drafted and unreviewed.
--
-- The two strands and their parts are added by the migration "schooling and language strands" (OpenLPM PR #146). This file stops with an error if
-- they are missing, so no link is skipped without notice. The parts start in draft status, and the comparison views read accepted parts only,
-- so these links appear in the views once a reviewer accepts the parts.
--
-- To undo: DELETE FROM curriculum_repository_links WHERE relation_type LIKE 'proposed\_%' AND data_object_id IN (SELECT id FROM lpm_data_objects WHERE parent_id IS NOT NULL AND project_id = (SELECT id FROM projects WHERE slug = 'interdisciplinary-lpm-synth') AND created_at >= '2026-10-30') AND repository_record_id IN (SELECT id FROM curriculum_repository_records WHERE source_record_id LIKE 'IN-%') AND created_at >= '2026-10-30';

SET search_path = public, extensions;

DO $MIGRATION$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM lpm_data_objects WHERE id = '4dba2f37-8343-5a95-8180-ec785af885fb'::uuid) THEN
    RAISE EXCEPTION 'Apply the schooling and language strands migration first: strand 4dba2f37-8343-5a95-8180-ec785af885fb is missing.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM lpm_data_objects WHERE id = '19a6d1e8-96b6-58c9-8dff-f68b0ad2fe84'::uuid) THEN
    RAISE EXCEPTION 'Apply the schooling and language strands migration first: strand 19a6d1e8-96b6-58c9-8dff-f68b0ad2fe84 is missing.';
  END IF;
END
$MIGRATION$;

INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-nep-2020-home-language-medium-and-three-language-formula', 'proposed_relates_to', 'Para 4.13 says the three languages are the choices of States, regions and students, and para 4.11 applies the home-language medium to public and private schools. The text names several parties in decisions about language in school, which fits the part''s task of naming who takes part in choosing what a school teaches.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-MANDATE-nep-2020-home-language-medium-and-three-language-formula', 'proposed_relates_to', 'Para 4.13 gives reasons for the three-language formula that refer to the aspirations of people, regions and the Union, and to national unity. That puts community, region and nation in one policy argument, which the part asks students to analyse by layers of purpose. The record states no conflict between layers.'),
  ('96a0304e-2ff9-54cb-bbb1-1b03d521e818', 'IN-MANDATE-nep-2020-languages-of-india-classical-languages-and-sign-language', 'proposed_relates_to', 'In Classes 6 to 8 every student is to learn how Indian languages relate: shared scripts and grammar, word origins, mutual influence and differences. The part asks students to tell apart ancestry, borrowing, imitated sounds and chance. The policy text names origins and influence and does not list chance.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-nep-2020-access-open-schooling-alternative-schools-and-boarding', 'proposed_relates_to', 'The record lists routes the policy names to schooling outside a regular school: open schooling at levels equal to Classes 3, 5, 8, 10 and 12, alternative centres, boarding and home-based education. It also cites 3.22 crore children with no school place. It shows who has access to school and how access is organised.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-nep-2020-early-childhood-care-anganwadi-and-preparatory-class', 'proposed_relates_to', 'The record shows the policy placing early learning in several kinds of centre (Anganwadis, pre-primary sections, stand-alone pre-schools) and in a Preparatory Class before Class 1. It is an example of how a system organises where and by whom young children are taught, which fits the part''s view of schooling as one organised arrangement.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-nep-2020-vocational-education-and-internships-in-school', 'proposed_relates_to', 'The policy has students in Classes 6 to 8 sample vocational crafts that States and local communities decide, and intern with local experts. It states an aim of overcoming the social status hierarchy attached to vocational education. This gives one purpose claimed for schools and one example of who takes part in choosing what is taught.'),
  ('5b73aa4d-166f-5856-bd57-b6e9aa396bde', 'IN-MANDATE-ncf-se-2023-language-education-aims-and-three-languages', 'proposed_relates_to', 'The framework says literacy should first happen in the language most familiar to the child, preferably the mother tongue. The part''s first task starts from the languages that children in one class already use. The framework does not discuss how words get their meaning.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-ncf-se-2023-language-education-aims-and-three-languages', 'proposed_relates_to', 'The framework says the state or other relevant bodies would decide the choices of R1, R2 and R3 offered to students, and that an Indian language must be available as an option for the medium of instruction up to Class 12. This names who decides about languages in school, which the part asks students to identify.'),
  ('5b73aa4d-166f-5856-bd57-b6e9aa396bde', 'IN-MANDATE-ncf-se-2023-language-stage-goals-nature-of-language-and-sign-language', 'proposed_relates_to', 'The framework says Indian Sign Language has its own grammar and style and that all students should be given basic familiarity with a few signs. It names no class and says schools could consider offering the language. The part counts sign languages as full languages from the first stage and has children compare spoken words, written words and signs.'),
  ('31b3931a-5cfe-5bdd-9a66-5fa460a63392', 'IN-MANDATE-ncf-se-2023-language-stage-goals-nature-of-language-and-sign-language', 'proposed_relates_to', 'The framework says languages change over time and take ideas from other languages. This lines up with the part''s task of giving an example of a word that moved from one language to another and saying what it was used for.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-rte-act-2009-right-to-schooling-ages-6-14-and-school-types', 'proposed_relates_to', 'The Act of 2009 makes free and compulsory education to Class 8 a legal right of every child aged six to fourteen and names four school types by who runs or funds them. It is a dated point for the part''s timeline of schooling for nearly every child, and it shows who has access to which type of school.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-rte-act-2009-who-sets-the-curriculum-mother-tongue-clause-and-parent-committees', 'proposed_relates_to', 'The Act says an academic authority named by each government lays down the curriculum for Classes 1 to 8 and that the Centre develops a national curriculum framework with that authority''s help. School committees of at least three-fourths parents monitor the school. It names who decides what is taught and who oversees the school.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-udise-plus-2024-25-schools-and-enrolment-by-management', 'proposed_relates_to', 'The 2024-25 table counts schools and students by who runs them: government, government-aided, private unaided and other schools, with residential schools counted separately. It gives a dated picture of how schooling is organised, which the part can set beside its timeline. A later report for 2025-26 exists, so this is one year only.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KA-MANDATE-supreme-court-2014-medium-of-instruction-classes-1-4-order-1994', 'proposed_relates_to', 'A state order set the language of teaching in Classes 1 to 4, school managements challenged it, and the Court said the parent or guardian decides a child''s mother tongue. This names several parties in one choice about schooling. The part asks learners to name who takes part in choosing what a school teaches.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-KA-MANDATE-supreme-court-2014-medium-of-instruction-classes-1-4-order-1994', 'proposed_relates_to', 'The Court''s five questions weigh the state, parents and guardians, linguistic minorities and school managements against each other on one policy. The part asks learners to analyse a policy argument across such layers and see where they pull apart.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KA-MANDATE-kannada-language-learning-act-2015', 'proposed_relates_to', 'A state law fixes one subject for every kind of school (state, local body, private, minority) and requires state-prescribed textbooks. It shows a government deciding part of what schools teach, which the part asks learners to describe.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MH-MANDATE-gr-corrigendum-2025-06-17-hindi-generally-third-language-classes-1-5', 'proposed_relates_to', 'A state order sets which language is third in Classes 1 to 5, allows another Indian language when 20 pupils of a class year ask for it, and names the officer who plans it. It shows who takes part in choosing what is taught.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MH-EVENT-third-language-orders-cancelled-2025-06-29-and-review-committee-report-2026-02', 'proposed_relates_to', 'The record names those involved in one decision about what children learn: a state department that issued the orders, the Chief Minister who announced their withdrawal, a review committee, and the cabinet that is to consider its report. The part asks learners to name who takes part in such a choice.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-UP-MANDATE-upmsp-language-subject-syllabi-classes-9-10-2026-27', 'proposed_relates_to', 'The Board lists 21 language subjects with a syllabus for each, and the four Class 9 syllabi read give a 70-mark paper and 30 internal marks. This shows a school board fixing which languages are offered as subjects in Classes 9 and 10 and how they are examined, one case of who decides what is taught.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KL-MANDATE-malayalam-language-learning-act-2017', 'proposed_relates_to', 'A state law says Malayalam is taught in every class from 1 to 10 in government, aided and unaided schools, including unaided CBSE and CISCE schools, and ties it to school recognition. It shows the legislature and government deciding part of what schools teach, with SCERT preparing textbooks where needed.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KL-MANDATE-kcf-2023-commissioning-consultation-and-national-positioning', 'proposed_relates_to', 'A Kerala government order of 9 March 2022 formed a core committee for the state''s curriculum revision, with the SCERT director as convener. The framework reports 26 focus groups and classroom talks with students. The 6-8 part asks pupils to name who takes part in choosing what a school teaches. This is a worked example.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KL-MANDATE-kcf-2023-aims-principles-stages-and-curricular-areas', 'proposed_relates_to', 'The framework, which SCERT''s page labels a draft, gives 16 aims, among them social justice and scientific temper. It sets out three stages: childcare from age 3, a primary stage of Classes 1 to 7 and a secondary stage of Classes 8 to 12. The 6-8 part asks pupils to name purposes people claim for schools.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KL-MANDATE-kcf-2023-aims-value-education-and-gender-justice', 'proposed_relates_to', 'The framework says values such as equality and freedom should be picked up through daily school life and debate in class, and calls a separate values item unacceptable. It places values teaching in school life, which bears on the 6-8 part''s purposes of schools and on what a school teaches without a lesson on it.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KL-MANDATE-kerala-school-curriculum-governance-scert-dge-pareeksha-bhavan-ssk', 'proposed_relates_to', 'The record names who prepares Kerala''s curriculum and textbooks (SCERT Kerala), who runs examinations and who supports ICT, and says press reports describe a steering committee approving textbook titles. It gives a Kerala answer to the 6-8 part''s question of who chooses what schools teach.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KL-MANDATE-kcf-2023-language-policy-and-mother-tongue-instruction', 'proposed_relates_to', 'Kerala''s framework says teaching should be in the mother tongue, with English from Class 1 and Hindi from Class 5, and SCERT lists textbooks in Malayalam, English, Tamil and Kannada media. The record shows one state''s language-of-instruction choice. It does not summarise the framework''s reasons or say who gains or loses, which the 6-8 part asks pupils to describe.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KL-EVENT-scert-additional-higher-secondary-textbooks-topics-dropped-by-ncert-2023-08', 'proposed_relates_to', 'SCERT Kerala published six additional textbooks in 2023 for Classes 11 and 12. The Director''s preface in the books read says they fill gaps left by topics deleted from the prescribed books, and each is read as a continuation of named NCERT chapters. It shows a named state body adding to what students study. The record gives no reason for either choice.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-ncf-se-2023-aims-curricular-areas-and-learning-standards', 'proposed_relates_to', 'The framework sets five aims for schooling, from rational thought and health to democratic, economic and cultural participation. The 6-8 part asks pupils to give purposes people have claimed for schools and to describe a case where they conflict. These aims are a national statement of such purposes.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MANDATE-nep-2020-constitutional-values-citizenship-and-ethical-reasoning', 'proposed_relates_to', 'The policy gives schools the task of building constitutional values such as empathy and justice, and lists citizenship skills and ethical reasoning for every student. These are purposes claimed for schooling, stated by a national ministry, which the 6-8 part asks pupils to name and compare.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-EVENT-ncert-2022-rationalised-content-democracy-movements-and-group-conflict-topics', 'proposed_relates_to', 'NCERT marked topics in its Class 6 to 12 books as dropped and not to be assessed, and gave its reasons: the pandemic, the NEP 2020 call for lighter content, and overlap. It is an example of a named body choosing what is taught and saying why, which the 6-8 part asks pupils to describe.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MH-MANDATE-scert-scf-school-education-2024-stages-and-subjects', 'proposed_relates_to', 'Maharashtra''s framework for Classes 3 to 12 uses the 5+3+3+4 stages, keeps Marathi compulsory to Class 12, and adopts NCERT science and mathematics books unchanged apart from local pictures and examples. It shows a state deciding which language is required and which books are used, the kind of choice the 6-8 part says people and groups make.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-MH-EVENT-gr-2025-04-16-phased-rollout-of-new-curriculum', 'proposed_relates_to', 'A Maharashtra order of 16 April 2025 brings the new curriculum in class by class from 2025-26 to 2028-29, names who supplies books and bridge courses, and makes Hindi a third language in Classes 1 to 5, an item later reports say was put on hold. It shows decisions on schooling made and revised by named authorities.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-UP-MANDATE-school-governance-two-boards', 'proposed_relates_to', 'The Basic Shiksha Parishad (1972 Act) organises basic education up to Class 8 outside high schools and intermediate colleges. The UP Board, set up in 1921, recognises schools, prescribes courses and textbooks, and runs the Class 10 and 12 examinations. The record says the body setting the syllabus for Classes 6 to 8 inside high schools is unconfirmed.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-UP-MANDATE-upmsp-ncert-textbooks-classes-9-12-2026-27', 'proposed_relates_to', 'For 2026-27 the UP Board adopted 70 NCERT textbooks for Classes 9 to 12, and told schools to teach from Board-authorised books at fixed prices and barred them from pushing other books or guides. It shows a state body choosing the written curriculum from a national body''s books, a choice the 6-8 part says people make.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KA-MANDATE-sep-commission-final-report-2025', 'proposed_relates_to', 'A press note on the Karnataka commission''s report recommends teaching in Kannada or the mother tongue up to Class 5, two languages, a 2+8+4 structure and a state-made curriculum in place of NCERT textbooks. These are choices about language of instruction and about who decides what is taught. They are recommendations, and no decision adopting them was found.'),
  ('712e4748-73c1-5809-8cbe-8fa0528b138b', 'IN-KA-MANDATE-textbook-revision-2014-17-ncf2005-kcf2007', 'proposed_relates_to', 'Front pages of two Karnataka state textbooks say Classes 1 to 10 were revised through 27 committees under orders of 2014 and 2015, with new books due in 2017-18. The Chief Minister asked for books that build equality and scientific temper, and three expert committees compared state books with NCERT. It shows who took part in this choice of what is taught.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-MANDATE-ncf-se-2023-aims-curricular-areas-and-learning-standards', 'proposed_relates_to', 'The five national aims mix purposes for the learner (rational thought, health) with purposes for society (democratic, economic and cultural participation). The 9-12 part asks students to analyse a policy argument by layers of purpose, and this short text lets them ask which layer each aim serves.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-KL-MANDATE-kcf-2023-commissioning-consultation-and-national-positioning', 'proposed_relates_to', 'The framework says Kerala does not take up every national suggestion because the national emphasis is access and retention while Kerala''s is quality and equity. This is a policy position in which the national and state layers of purpose differ, which the 9-12 part asks students to analyse.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-KA-MANDATE-sep-commission-final-report-2025', 'proposed_relates_to', 'The commission''s report recommends a state curriculum and a 2+8+4 structure in place of reliance on NCERT textbooks. News reports say a Cabinet sub-committee was set up in May 2026 to review it. It gives students a proposal in which the state and national layers of purpose can be compared, as the 9-12 part asks.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-MANDATE-ncf-se-2023-ai-and-computing-in-school', 'proposed_relates_to', 'The framework says students and teachers should understand in basic terms how AI and generative AI work and how to judge their use. It names biased output, data privacy and students handing their thinking to AI as risks. This is a national statement of what students should understand about AI, one part of the 9-12 part''s question of what must be taught.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-MH-EVENT-scert-circular-2026-07-15-ai-saathi-for-educators', 'proposed_relates_to', 'A circular of 15 July 2026 asks every teacher of Classes 1 to 12 to finish an online course on basic AI and machine learning, uses of AI in teaching and school administration, and responsible use. It counts for 4 of the 50 yearly training hours. It shows an authority responding to AI through teacher training and gives no student syllabus.'),
  ('a9c1777a-a159-534d-b927-ad30da661ce6', 'IN-KL-MANDATE-kcf-2023-ict-coding-ai-robotics-across-subjects', 'proposed_relates_to', 'Kerala''s framework, which SCERT''s page labels a draft, suggests AI-supported search chat boxes for digital learning resources, lists AI, data analytics and robotics as content to add, and names AI as a possible optional secondary subject, all as proposals. It shows a framework proposing how a new tool enters teaching and what is added to the curriculum.'),
  ('19fe4450-380b-5a74-bbac-35de01bad5e7', 'IN-KL-MANDATE-kcf-2023-language-policy-and-mother-tongue-instruction', 'proposed_relates_to', 'Kerala''s framework says learners can take Tamil, Kannada, Arabic, Sanskrit or Urdu as a first language beside Malayalam, and that teaching should be in the mother tongue with regional dialects respected. The 9-12 part asks how the choice of language of instruction bears on what a community can pass on. The record says nothing on language loss.'),
  ('19fe4450-380b-5a74-bbac-35de01bad5e7', 'IN-MH-MANDATE-scert-scf-school-education-2024-science', 'proposed_relates_to', 'Maharashtra''s Marathi science competencies word three points differently from the national English text, among them ''related to evolution'' against ''inheritance of traits'' and ''creation of the living world'' against ''spontaneous generation of life''. The record''s English glosses of the Marathi still need a Marathi reader to confirm. This fits the 9-12 part''s check on translated key ideas.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);
